-- Migración 0006. Crea LOTES y sus productos como referencias externas.
-- PADRE_ID arma el árbol de empaque. La caja es un LOTES_TIPOS, no una tabla.
-- No editar este archivo. El siguiente cambio va en una migración nueva
-- y debe reflejarse en db/init.sql.

CREATE TABLE "LOTES" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ID_TIPO" integer NOT NULL,
  "PADRE_ID" integer,
  CONSTRAINT "LOTES_ID_TIPO_FK"
    FOREIGN KEY ("ID_TIPO") REFERENCES "LOTES_TIPOS" ("ID"),
  CONSTRAINT "LOTES_PADRE_ID_FK"
    FOREIGN KEY ("PADRE_ID") REFERENCES "LOTES" ("ID"),
  CONSTRAINT "LOTES_PADRE_ID_CHK" CHECK (
    "PADRE_ID" IS NULL OR "PADRE_ID" <> "ID"
  )
);

CREATE INDEX "LOTES_ID_TIPO_IDX" ON "LOTES" ("ID_TIPO");

CREATE INDEX "LOTES_PADRE_ID_IDX" ON "LOTES" ("PADRE_ID");

CREATE TABLE "LOTES_PRODUCTOS" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ID_LOTE" integer NOT NULL,
  "ID_PRODUCTO" integer,
  "CLAVE_PRODUCTO" text,
  CONSTRAINT "LOTES_PRODUCTOS_ID_LOTE_FK"
    FOREIGN KEY ("ID_LOTE") REFERENCES "LOTES" ("ID") ON DELETE CASCADE,
  CONSTRAINT "LOTES_PRODUCTOS_ID_PRODUCTO_CHK" CHECK (
    "ID_PRODUCTO" IS NULL OR "ID_PRODUCTO" > 0
  ),
  CONSTRAINT "LOTES_PRODUCTOS_CLAVE_PRODUCTO_CHK" CHECK (
    "CLAVE_PRODUCTO" IS NULL OR length(btrim("CLAVE_PRODUCTO")) > 0
  ),
  CONSTRAINT "LOTES_PRODUCTOS_REFERENCIA_CHK" CHECK (
    "ID_PRODUCTO" IS NOT NULL OR "CLAVE_PRODUCTO" IS NOT NULL
  )
);

CREATE INDEX "LOTES_PRODUCTOS_ID_LOTE_IDX" ON "LOTES_PRODUCTOS" ("ID_LOTE");
